 void home(){shell("آزمون‌ساز حرفه‌ای"); TextView intro=tv("آزمون‌های من",24,true);body.addView(intro);TextView sub=tv("ساخت آزمون فارسی و دریافت خروجی PDF",14,false);sub.setTextColor(muted);body.addView(sub); Button add=button("＋ ساخت آزمون جدید");LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(52));ap.setMargins(0,dp(14),0,dp(16));body.addView(add,ap);add.setOnClickListener(v->selectTemplate()); if(exams.length()==0){TextView empty=tv("هنوز آزمونی نساخته‌اید\nبرای شروع روی دکمه بالا بزنید.",17,false);empty.setGravity(Gravity.CENTER);empty.setTextColor(muted);empty.setPadding(0,dp(80),0,0);body.addView(empty);} for(int i=exams.length()-1;i>=0;i--) addCard(exams.optJSONObject(i),i);}
 void addCard(JSONObject e,int index){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(14),dp(10),dp(14),dp(12));c.setBackground(bg(Color.WHITE,14));TextView t=tv(e.optString("title"),18,true);c.addView(t);TextView m=tv("درس: "+e.optString("course")+"  •  "+e.optJSONArray("questions").length()+" سؤال",13,false);m.setTextColor(muted);c.addView(m);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.LEFT);Button pdf=button("خروجی PDF");Button del=button("حذف");del.setTextColor(Color.rgb(190,18,60));del.setBackground(bg(Color.rgb(255,241,242),10));row.addView(pdf,new LinearLayout.LayoutParams(0,dp(44),1));LinearLayout.LayoutParams d=new LinearLayout.LayoutParams(0,dp(44),1);d.setMargins(dp(8),0,0,0);row.addView(del,d);c.addView(row);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,0,0,dp(12));body.addView(c,cp);pdf.setOnClickListener(v->generatePdf(e));del.setOnClickListener(v->confirmDelete(index));}
 void confirmDelete(int i){new AlertDialog.Builder(this).setTitle("حذف آزمون").setMessage("این آزمون حذف شود؟").setNegativeButton("انصراف",null).setPositiveButton("حذف",(d,w)->{exams.remove(i);save();home();}).show();}
 void selectTemplate(){shell("انتخاب قالب");body.addView(tv("ابتدا قالب آزمون را انتخاب کنید",20,true));Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,templateNames));body.addView(sp,new LinearLayout.LayoutParams(-1,dp(58)));Button scan=button("اسکن قالب و ادامه");LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(54));bp.setMargins(0,dp(18),0,0);body.addView(scan,bp);scan.setOnClickListener(v->{int idx=sp.getSelectedItemPosition();new AlertDialog.Builder(this).setTitle("اسکن قالب").setMessage("ساختار سربرگ، جدول‌ها، ردیف‌ها و ستون بارم بررسی شد.").setPositiveButton("ورود مشخصات",(d,w)->createExam(idx)).show();});}
 void createExam(int selectedIndex){shell("مشخصات اختصاصی قالب");boolean university=(selectedIndex<=14)||(selectedIndex>=18&&selectedIndex<=20);String[] hs=university?new String[]{"عنوان آزمون *","نام درس *","نام استاد","نام دانشگاه / دانشکده","رشته / شماره درس","تاریخ آزمون","ساعت آزمون","سال تحصیلی / نیمسال","مدت آزمون (دقیقه)","نمره کل","متن بالای سربرگ"}:new String[]{"عنوان آزمون *","نام درس *","نام دبیر","نام مدرسه / منطقه","پایه / رشته / کلاس","تاریخ آزمون","ساعت آزمون","سال تحصیلی / نوبت","مدت آزمون (دقیقه)","نمره کل","متن بالای سربرگ"};EditText[] f=new EditText[hs.length];for(int i=0;i<hs.length;i++){f[i]=field(hs[i]);body.addView(f[i]);}f[8].setInputType(2);f[8].setText("60");f[9].setInputType(8194);f[9].setText("20");TextView l=tv("قالب انتخاب‌شده: "+templateNames[selectedIndex],14,true);body.addView(l);Button next=button("ذخیره و افزودن سؤال");LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,dp(54));np.setMargins(0,dp(18),0,0);body.addView(next,np);next.setOnClickListener(v->{if(f[0].getText().toString().trim().isEmpty()||f[1].getText().toString().trim().isEmpty()){toast("عنوان و نام درس الزامی است");return;}current=new JSONObject();try{current.put("title",f[0].getText());current.put("course",f[1].getText());current.put("teacher",f[2].getText());current.put("school",f[3].getText());current.put("grade",f[4].getText());current.put("date",f[5].getText());current.put("time",f[6].getText());current.put("academicYear",f[7].getText());current.put("duration",f[8].getText());current.put("score",f[9].getText());current.put("headerText",f[10].getText());current.put("template",templateNames[selectedIndex]);current.put("templateIndex",selectedIndex);current.put("questions",new JSONArray());}catch(Exception x){}draftQs.clear();questionScreen();});}
 void questionScreen(){shell("افزودن سؤال  •  شماره "+fa(draftQs.size()+1));TextView count=tv("تا اینجا "+fa(draftQs.size())+" سؤال ثبت شده",14,false);count.setTextColor(muted);body.addView(count);Spinner type=new Spinner(this);String[] types={"چهارگزینه‌ای","صحیح / غلط","تشریحی","جای خالی"};type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,types));body.addView(type,new LinearLayout.LayoutParams(-1,dp(52)));EditText q=field("متن سؤال *");q.setSingleLine(false);q.setMinLines(3);body.addView(q,new LinearLayout.LayoutParams(-1,dp(110)));EditText[] op=new EditText[4];String[] oh={"گزینه الف","گزینه ب","گزینه ج","گزینه د"};for(int i=0;i<4;i++){op[i]=field(oh[i]);body.addView(op[i]);}Spinner ans=new Spinner(this);ans.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"پاسخ صحیح: الف","پاسخ صحیح: ب","پاسخ صحیح: ج","پاسخ صحیح: د"}));body.addView(ans,new LinearLayout.LayoutParams(-1,dp(52)));EditText score=field("بارم سؤال");score.setInputType(8194);score.setText("1");body.addView(score);type.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView a){}public void onItemSelected(android.widget.AdapterView a,View v,int p,long id){for(EditText e:op)e.setVisibility(p==0?View.VISIBLE:View.GONE);ans.setVisibility(p==0?View.VISIBLE:View.GONE);}});LinearLayout row=new LinearLayout(this);Button another=button("ثبت و سؤال بعد");Button finish=button("پایان و ذخیره");row.addView(another,new LinearLayout.LayoutParams(0,dp(54),1));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(0,dp(54),1);fp.setMargins(dp(8),0,0,0);row.addView(finish,fp);body.addView(row);View.OnClickListener saveQ=v->{if(q.getText().toString().trim().isEmpty()){toast("متن سؤال را وارد کنید");return;}JSONObject o=new JSONObject();try{o.put("text",q.getText());o.put("type",types[type.getSelectedItemPosition()]);o.put("score",score.getText());o.put("answer",new String[]{"الف","ب","ج","د"}[ans.getSelectedItemPosition()]);JSONArray a=new JSONArray();for(EditText e:op)a.put(e.getText().toString());o.put("options",a);}catch(Exception x){}draftQs.add(o);if(v==finish){finishExam();}else questionScreen();};another.setOnClickListener(saveQ);finish.setOnClickListener(saveQ);}
 void finishExam(){try{JSONArray a=current.getJSONArray("questions");for(JSONObject q:draftQs)a.put(q);exams.put(current);}catch(Exception e){}save();toast("آزمون ذخیره شد");home();}
 void generatePdf(JSONObject e){try{JSONArray qs=e.getJSONArray("questions");File dir=getExternalFilesDir(android.os.Environment.DIRECTORY_DOCUMENTS);if(dir!=null&&!dir.exists())dir.mkdirs();File outFile=new File(dir,"exam_itext7_"+System.currentTimeMillis()+".pdf");int ti=e.optInt("templateIndex",0);String asset=String.format(java.util.Locale.US,"templates/template_%02d.pdf",ti+1);File template=new File(getCacheDir(),"itext_template.pdf");copyAsset(asset,template);com.itextpdf.kernel.pdf.PdfDocument src=new com.itextpdf.kernel.pdf.PdfDocument(new com.itextpdf.kernel.pdf.PdfReader(template));com.itextpdf.kernel.pdf.PdfDocument dest=new com.itextpdf.kernel.pdf.PdfDocument(new com.itextpdf.kernel.pdf.PdfWriter(outFile));int perPage=6,total=Math.max(1,(qs.length()+perPage-1)/perPage);for(int pageNo=0;pageNo<total;pageNo++){int sourcePage=Math.min(pageNo+1,src.getNumberOfPages());src.copyPagesTo(sourcePage,sourcePage,dest);com.itextpdf.kernel.pdf.PdfPage page=dest.getLastPage();Bitmap overlay=makeQuestionOverlay(e,qs,pageNo*perPage,Math.min(qs.length(),(pageNo+1)*perPage),pageNo==0);ByteArrayOutputStream bos=new ByteArrayOutputStream();overlay.compress(Bitmap.CompressFormat.PNG,100,bos);com.itextpdf.io.image.ImageData img=com.itextpdf.io.image.ImageDataFactory.create(bos.toByteArray());com.itextpdf.kernel.pdf.canvas.PdfCanvas pc=new com.itextpdf.kernel.pdf.canvas.PdfCanvas(page.newContentStreamAfter(),page.getResources(),dest);com.itextpdf.kernel.geom.Rectangle r=page.getPageSize();pc.addImageFittedIntoRectangle(img,new com.itextpdf.kernel.geom.Rectangle(r.getLeft(),r.getBottom(),r.getWidth(),r.getHeight()),false);overlay.recycle();}src.close();dest.close();new AlertDialog.Builder(this).setTitle("PDF با iText 7 ساخته شد ✓").setMessage("قالب «"+e.optString("template")+"» اعمال شد.\n\n"+outFile.getAbsolutePath()).setPositiveButton("باشه",null).show();}catch(Exception x){toast("خطای iText 7: "+x.getMessage());}}
 void copyAsset(String name,File target)throws Exception{InputStream in=getAssets().open(name);FileOutputStream out=new FileOutputStream(target);byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);in.close();out.close();}
 Bitmap makeQuestionOverlay(JSONObject exam,JSONArray qs,int from,int to,boolean firstPage)throws Exception{Bitmap bm=Bitmap.createBitmap(1190,1684,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bm);c.drawColor(Color.TRANSPARENT,android.graphics.PorterDuff.Mode.CLEAR);Paint p=new Paint(1);p.setColor(Color.BLACK);p.setTypeface(Typeface.create("sans",Typeface.NORMAL));int template=exam.optInt("templateIndex",0);int[] rows=scanTemplateRows(template);if(firstPage&&template==12){p.setTextSize(17);p.setTypeface(Typeface.DEFAULT);p.setTextAlign(Paint.Align.RIGHT);c.drawText(exam.optString("teacher"),1080,145,p);c.drawText(exam.optString("course"),1080,180,p);c.drawText(exam.optString("grade"),1080,215,p);p.setTextAlign(Paint.Align.LEFT);c.drawText(exam.optString("date"),110,110,p);c.drawText(exam.optString("time"),110,145,p);c.drawText(exam.optString("duration")+" دقیقه",110,180,p);p.setTextAlign(Paint.Align.CENTER);c.drawText(exam.optString("title"),595,315,p);c.drawText(exam.optString("score"),700,350,p);}int largest=-1,largestAt=-1;for(int z=0;z<rows.length-1;z++){int gap=rows[z+1]-rows[z];if(rows[z]>250&&gap>largest){largest=gap;largestAt=z;}}boolean blankArea=largest>380;int ri=0;float flowY=360;float areaBottom=1580;if(blankArea){flowY=rows[largestAt]+38;areaBottom=rows[largestAt+1]-20;ri=rows.length;}else{while(ri<rows.length&&rows[ri]<300)ri++;flowY=ri<rows.length?rows[ri]+30:360;}for(int i=from;i<to;i++){JSONObject q=qs.getJSONObject(i);boolean descriptive=!q.optString("type").equals("چهارگزینه‌ای")&&!q.optString("type").equals("صحیح / غلط");int need=descriptive?135:92;float start=flowY,end=start+need;if(!blankArea&&ri<rows.length-1){start=rows[ri];int rj=ri+1;while(rj<rows.length&&rows[rj]-start<need)rj++;if(rj<rows.length){end=rows[rj];ri=rj;flowY=end+34;}else{flowY=end+25;ri=rows.length;}}else{flowY=end+24;if(flowY>areaBottom)flowY=areaBottom;}p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(19);c.drawText(q.optString("score","1"),70,start+32,p);p.setTextAlign(Paint.Align.RIGHT);p.setTextSize(22);c.drawText(fa(i+1)+")  "+q.optString("text"),1095,start+32,p);p.setTypeface(Typeface.DEFAULT);p.setTextSize(18);float y=start+70;if(q.optString("type").equals("چهارگزینه‌ای")){JSONArray ar=q.getJSONArray("options");for(int j=0;j<4;j++)c.drawText(new String[]{"الف","ب","ج","د"}[j]+") "+ar.optString(j),1070-(j%2)*480,y+(j/2)*36,p);}else if(q.optString("type").equals("صحیح / غلط")){c.drawText("□ صحیح                 □ غلط",1070,y,p);}}return bm;}
 int[] scanTemplateRows(int template){ArrayList<Integer> result=new ArrayList<>();android.graphics.pdf.PdfRenderer renderer=null;android.os.ParcelFileDescriptor fd=null;Bitmap bm=null;try{String name=String.format(java.util.Locale.US,"templates/template_%02d.pdf",template+1);File tmp=new File(getCacheDir(),"scan_template.pdf");copyAsset(name,tmp);fd=android.os.ParcelFileDescriptor.open(tmp,android.os.ParcelFileDescriptor.MODE_READ_ONLY);renderer=new android.graphics.pdf.PdfRenderer(fd);android.graphics.pdf.PdfRenderer.Page pg=renderer.openPage(0);bm=Bitmap.createBitmap(1190,1684,Bitmap.Config.ARGB_8888);bm.eraseColor(Color.WHITE);pg.render(bm,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_PRINT);pg.close();AdvancedTemplateScanner.Result scan=AdvancedTemplateScanner.analyze(bm);for(int line:scan.horizontalLines)result.add(line);}catch(Exception e){}finally{if(bm!=null)bm.recycle();try{if(renderer!=null)renderer.close();}catch(Exception e){}try{if(fd!=null)fd.close();}catch(Exception e){}}int[] out=new int[result.size()];for(int i=0;i<out.length;i++)out[i]=result.get(i);return out;}
 void load(){try{String s=getSharedPreferences("db",0).getString("exams","[]");exams=new JSONArray(s);}catch(Exception e){exams=new JSONArray();}}
 void save(){getSharedPreferences("db",0).edit().putString("exams",exams.toString()).apply();}
 String fa(Object x){String s=String.valueOf(x);String a="0123456789",b="۰۱۲۳۴۵۶۷۸۹";for(int i=0;i<10;i++)s=s.replace(a.charAt(i),b.charAt(i));return s;}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
